-- Create views for typed fact tables over raw_ingest
CREATE VIEW events_view AS SELECT T1.ts, T1.machine_id, T1.reason_code, T1.duration_s, T1.energy_kwh FROM raw_ingest AS T1 INNER JOIN jsonb_each(T1.payload) AS T2 ON T1.source = 'events' AND T2.key = 'event' AND T2.value::jsonb->>'machine_id' = T1.machine_id;

CREATE VIEW samples_view AS SELECT T1.ts, T1.machine_id, T1.tag, T1.value FROM raw_ingest AS T1 INNER JOIN jsonb_each(T1.payload) AS T2 ON T1.source = 'samples' AND T2.key = 'sample' AND T2.value::jsonb->>'machine_id' = T1.machine_id AND T2.value::jsonb->>'tag' = T1.tag;

-- Add indexes for performance
CREATE INDEX idx_events_machine_time ON events(machine_id, ts);
CREATE INDEX idx_samples_machine_time ON samples(machine_id, ts);
CREATE INDEX idx_raw_ingest_source ON raw_ingest(source);
CREATE INDEX idx_ingest_watermark_source ON ingest_watermark(source);
